	fn bare_wide_letter(value u32) bool {
		mut low := 0
		mut high := 659
		for low < high {
			middle := low + (high - low) / 2
			first := bare_character_word(bare_letter_ranges, middle * 12)
			last := bare_character_word(bare_letter_ranges, middle * 12 + 4)
			if value < first {
				high = middle
			} else if value > last {
				low = middle + 1
			} else {
				return (value - first) % bare_character_word(bare_letter_ranges, middle * 12 + 8) == 0
			}
		}
		return false
	}
}
